<?php
require __DIR__ . '/records.php'; exit; __halt_compiler();
require_once __DIR__ . '/../../config/config.php';
require_roles(['ADMIN','HR']);
$pdo = db(); 
$employeeId = (int) ($_GET['employee_id'] ?? $_POST['employee_id'] ?? 0);
$employees = $pdo->query('SELECT id,employee_number,first_name,last_name FROM employees ORDER BY last_name')->fetchAll();
$types = $pdo->query('SELECT id,name FROM document_types WHERE is_active=1 ORDER BY name')->fetchAll();
$templates = $pdo->query('SELECT id,name FROM document_templates WHERE is_active=1 ORDER BY name')->fetchAll();
$error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
	verify_csrf(); phase2_require_employee($pdo, $employeeId);
	try {
		if (($_POST['form_action'] ?? '') === 'document') {
			if (empty($_POST['title']) || empty($_POST['document_type_id'])) throw new InvalidArgumentException('Title and document type are required.');
			$pdo->prepare('INSERT INTO employee_documents (employee_id,document_type_id,title,description,issue_date,effective_date,expiration_date,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$employeeId,$_POST['document_type_id'],trim($_POST['title']),post_value('description'),valid_date(post_value('issue_date')),valid_date(post_value('effective_date')),valid_date(post_value('expiration_date')),$_SESSION['user_id']]);
			audit('DOCUMENT_CREATED','employee_documents',(int) $pdo->lastInsertId()); flash('success','Employee document added.');
		} elseif (($_POST['form_action'] ?? '') === 'draft') {
			$statement = $pdo->prepare('SELECT * FROM document_templates WHERE id=? AND is_active=1'); $statement->execute([(int) $_POST['template_id']]); $template = $statement->fetch();
			if (!$template) throw new InvalidArgumentException('Select a valid template.');
			$employee = phase2_require_employee($pdo,$employeeId); $content = render_template($template['content'],$employee);
			$pdo->prepare('INSERT INTO document_drafts (employee_id,document_type_id,template_id,title,content,created_by) VALUES (?,?,?,?,?,?)')->execute([$employeeId,$template['document_type_id'],$template['id'],$template['name'],$content,$_SESSION['user_id']]);
			$draftId=(int)$pdo->lastInsertId(); $pdo->prepare('INSERT INTO document_versions (draft_id,version_number,content,change_description,created_by) VALUES (?,?,?,?,?)')->execute([$draftId,1,$content,'Initial draft',$_SESSION['user_id']]); audit('DRAFT_CREATED','document_drafts',$draftId); flash('success','Draft created.');
		}
		redirect('admin/employee-records/index.php?employee_id='.$employeeId);
	} catch (Throwable $exception) { $error = $exception->getMessage(); }
}
$employee = $employeeId ? phase2_employee($pdo,$employeeId) : null; $documents=[]; $drafts=[];
if ($employee) { $s=$pdo->prepare('SELECT d.*,t.name type_name,u.username FROM employee_documents d JOIN document_types t ON t.id=d.document_type_id LEFT JOIN users u ON u.id=d.created_by WHERE d.employee_id=? ORDER BY d.created_at DESC');$s->execute([$employeeId]);$documents=$s->fetchAll();$s=$pdo->prepare('SELECT d.*,t.name type_name FROM document_drafts d JOIN document_types t ON t.id=d.document_type_id WHERE d.employee_id=? ORDER BY d.updated_at DESC');$s->execute([$employeeId]);$drafts=$s->fetchAll(); }
