verflow-x-auto mt-4"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Title</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody class="divide-y"><?php foreach($drafts as $draft):?><tr><td class="py-3 font-bold"><?=e($draft['title'])?></td><td><?=e($draft['type_name'])?></td><td><?=e($draft['status'])?></td><td><a class="font-bold text-teal-700" href="draft.php?id=<?=$draft['id']?>">Open</a></td></tr><?php endforeach;?></tbody></table><?php if(!$drafts):?><p class="py-4 text-sm text-slate-500">No drafts yet.</p><?php endif;?></div></section></div><?php endif;?><?php require __DIR__.'/../../includes/footer.php';
